        {text = "便能夠選用秘密人物。試試看吧！", x = 1, y = 93, w = 202, h = 12, pad = 0, tx = 1, ty = 92, align = "left", room = 401, size = 13, color = 0xffffff, back = 0x000000, group = "1_40"},
        {text = "Congratulations, you have finished the stage mode.", x = 1, y = 119, w = 396, h = 13, pad = 0, tx = 1, ty = 117, align = "left", room = 402, size = 14, color = 0xffffff, back = 0x000000, group = "1_119"},
        {text = "To reveal the secret characters,", x = 1, y = 131, w = 252, h = 13, pad = 0, tx = 1, ty = 129, align = "left", room = 401, size = 14, color = 0xffffff, back = 0x000000, group = "1_119"},
        {text = "just type \"lf2.net\" at character selection menu!", x = 2, y = 145, w = 379, h = 13, pad = 0, tx = 2, ty = 143, align = "left", room = 400, size = 14, color = 0xffffff, back = 0x000000, group = "1_119"},
        {text = "很感激您對這遊戲的支持.", x = 1, y = 159, w = 158, h = 12, pad = 0, tx = 1, ty = 157, align = "left", room = 401, size = 14, color = 0xffffff, back = 0x000000, group = "1_119"},
        {text = "您知道嗎？我們自小便夢想能做出一個在世界各地流行的遊戲，", x = 1, y = 172, w = 384, h = 12, pad = 0, tx = 1, ty = 170, align = "left", room = 401, size = 14, color = 0xffffff, back = 0x000000, group = "1_119"},
        {text = "現在，這個夢想似乎達到了！希望十年、二十年之後，LF2", x = 1, y = 185, w = 364, h = 12, pad = 0, tx = 1, ty = 183, align = "left", room = 401, size = 14, color = 0xffffff, back = 0x000000, group = "1_119"},
        {text = "仍會留在每一位玩家的心裏面！", x = 1, y = 198, w = 186, h = 12, pad = 0, tx = 1, ty = 196, align = "left", room = 401, size = 14, color = 0xffffff, back = 0x000000, group = "1_119"},
        {text = "Thank you very much for your support in LF2.", x = 1, y = 224, w = 348, h = 14, pad = 0, tx = 1, ty = 222, align = "left", room = 401, size = 14, color = 0xffffff, back = 0x000000, group = "1_119"},
        {text = "Do you know? It has always been our dreams to", x = 2, y = 236, w = 366, h = 14, pad = 0, tx = 2, ty = 234, align = "left", room = 400, size = 14, color = 0xffffff, back = 0x000000, group = "1_119"},
        {text = "create a global popular game, and seem to me now,", x = 2, y = 249, w = 387, h = 15, pad = 0, tx = 2, ty = 248, align = "left", room = 400, size = 14, color = 0xffffff, back = 0x000000, group = "1_119"},
        {text = "our goal has been achieved!", x = 2, y = 262, w = 211, h = 14, pad = 0, tx = 2, ty = 260, align = "left", room = 232, size = 14, color = 0xffffff, back = 0x000000, group = "1_119"},
        {text = "we hope LF2 will", x = 233, y = 263, w = 125, h = 13, pad = 0, tx = 233, ty = 261, align = "left", room = 169, size = 13, color = 0xffffff, back = 0x000000},
        {text = "leave a print in every player's heart!", x = 2, y = 274, w = 316, h = 17, pad = 0, tx = 2, ty = 274, align = "left", room = 329, size = 14, color = 0xffffff, back = 0x000000, group = "1_119"},
        {text = "After", x = 329, y = 276, w = 38, h = 10, pad = 0, tx = 367, ty = 273, align = "right", room = 66, size = 12, color = 0xffffff, back = 0x000000},
