        {text = "hope you all will still", x = 186, y = 287, w = 180, h = 15, pad = 0, tx = 366, ty = 286, align = "right", room = 227, size = 14, color = 0xffffff, back = 0x000000},
        {text = "remember the game!", x = 2, y = 302, w = 139, h = 12, pad = 0, tx = 2, ty = 299, align = "left", room = 400, size = 14, color = 0xffffff, back = 0x000000, group = "1_119"},
        {text = "LF2 完成後，我們好應該返回自己的工作崗位了.", x = 2, y = 316, w = 303, h = 12, pad = 0, tx = 2, ty = 314, align = "left", room = 417, size = 14, color = 0xffffff, back = 0x000000, group = "1_119"},
        {text = "在人生中，能找到一個願意一起去追求理想的伙伴是一件很難的事，", x = 1, y = 342, w = 412, h = 12, pad = 0, tx = 1, ty = 340, align = "left", room = 418, size = 14, color = 0xffffff, back = 0x000000, group = "1_119"},
        {text = "但願有一天，我們仍能有合作的機會，創作更多精彩的遊戲！", x = 1, y = 355, w = 372, h = 12, pad = 0, tx = 1, ty = 353, align = "left", room = 418, size = 14, color = 0xffffff, back = 0x000000, group = "1_119"},
        {text = "After LF2 is finished, we shall all go back to", x = 1, y = 381, w = 367, h = 12, pad = 0, tx = 1, ty = 379, align = "left", room = 418, size = 13, color = 0xffffff, back = 0x000000, group = "1_381"},
        {text = "our job duties...", x = 2, y = 394, w = 131, h = 12, pad = 0, tx = 2, ty = 392, align = "left", room = 151, size = 13, color = 0xffffff, back = 0x000000, group = "1_381"},
        {text = "Marti will try establishing his", x = 153, y = 393, w = 246, h = 14, pad = 0, tx = 399, ty = 391, align = "right", room = 295, size = 14, color = 0xffffff, back = 0x000000},
        {text = "own career, while Starsky will continue his studies", x = 2, y = 407, w = 405, h = 12, pad = 0, tx = 2, ty = 405, align = "left", room = 417, size = 13, color = 0xffffff, back = 0x000000, group = "1_381"},
        {text = "in the US (UCLA). It is an exceptionally fine", x = 2, y = 418, w = 358, h = 15, pad = 0, tx = 2, ty = 417, align = "left", room = 417, size = 13, color = 0xffffff, back = 0x000000, group = "1_381"},
        {text = "incidence to meet somebody who will strive for the", x = 2, y = 431, w = 398, h = 16, pad = 0, tx = 2, ty = 431, align = "left", room = 417, size = 13, color = 0xffffff, back = 0x000000, group = "1_381"},
        {text = "same goal.", x = 2, y = 446, w = 75, h = 14, pad = 0, tx = 2, ty = 445, align = "left", room = 96, size = 13, color = 0xffffff, back = 0x000000, group = "1_381"},
        {text = "Hope there will be one day we can have", x = 98, y = 444, w = 302, h = 16, pad = 0, tx = 400, ty = 441, align = "right", room = 330, size = 17, color = 0xffffff, back = 0x000000},
        {text = "opportunity to work together again, to create a more", x = 2, y = 458, w = 414, h = 14, pad = 0, tx = 2, ty = 457, align = "left", room = 420, size = 13, color = 0xffffff, back = 0x000000, group = "1_381"},
        {text = "fantastic game!", x = 1, y = 471, w = 116, h = 14, pad = 0, tx = 1, ty = 470, align = "left", room = 418, size = 13, color = 0xffffff, back = 0x000000, group = "1_381"},
        {text = "最後再一次多謝大家. LF2 萬歲！", x = 1, y = 486, w = 206, h = 12, pad = 0, tx = 1, ty = 485, align = "left", room = 418, size = 13, color = 0xffffff, back = 0x000000, group = "1_381"},
        {text = "Thank you again for all your support. Long live LF2!", x = 1, y = 499, w = 412, h = 13, pad = 0, tx = 1, ty = 497, align = "left", room = 418, size = 13, color = 0xffffff, back = 0x000000, group = "1_381"},
