        {text = "This competition is to celebrate the 10th year anniversary of LF2. From time to time, we will", x = 48, y = 479, w = 528, h = 11, pad = 0, tx = 312, ty = 478, align = "center", room = 534, size = 10, color = 0xc5d1ff, back = 0x000000},
